    main()

"""Demo: build the explicit positions and print their ordinal game values.

Reproduces the strictly increasing hierarchy 1 < omega < omega^2 < ... < omega^omega
by evaluating the game value of each explicit construction.
"""
from __future__ import annotations
from typing import List, Tuple


def cnf_str(cnf: Tuple[Tuple[int, int], ...], top: bool = False) -> str:
    if top:
        return "omega^omega"
    if not cnf:
        return "0"
    out: List[str] = []
    for e, c in cnf:
        if e == 0:
            out.append(str(c))
        elif e == 1:
            out.append("omega" if c == 1 else f"omega*{c}")
        else:
            out.append(f"omega^{e}" if c == 1 else f"omega^{e}*{c}")
    return " + ".join(out)


def main() -> None:
    # opowGame(n) has value omega^n; the diagonal has value omega^omega.
    print("Explicit infinite-chess positions and their game values:")
    print(f"  opowGame(0) : value = {cnf_str(((0, 1),))}")
    for n in range(1, 6):
        print(f"  opowGame({n}) : value = {cnf_str(((n, 1),))}")
    print(f"  omegaOmegaGame : value = {cnf_str((), top=True)}")
    print("\nHierarchy: 1 < omega < omega^2 < omega^3 < omega^4 < omega^5 < ... < omega^omega")


if __name__ == "__main__":
    main()

